// Normalize Lead & Generate Deterministic Fingerprint
const item = $json.body || $json;

const businessName = (item.business_name || '').trim();
const phone = (item.phone || '').replace(/[^0-9+]/g, '');
const city = (item.city || '').trim().toLowerCase();

if (!businessName || !phone) {
  throw new Error('Missing required lead fields: business_name or phone');
}

const normName = businessName.toLowerCase().replace(/[^a-z0-9]/g, '');
const normPhone = phone.replace(/[^0-9]/g, '');
const fingerprint = `${normName}_${normPhone}_${city}`;

return [{
  json: {
    fingerprint,
    business_name: businessName,
    category: item.category || 'Local Business',
    phone: phone,
    address: item.address || '',
    city: item.city || 'Nagpur',
    country: item.country || 'India',
    google_maps_url: item.google_maps_url || null,
    google_rating: item.google_rating ? parseFloat(item.google_rating) : null,
    google_reviews: item.google_reviews ? parseInt(item.google_reviews, 10) : 0,
    website: item.website || null,
    source: item.source || 'google_maps',
    status: 'READY_TO_CALL',
    call_status: 'NOT_CALLED',
    call_attempts: 0,
    max_attempts: 3,
    created_at: new Date().toISOString()
  }
}];
